package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.OwnerIdentity;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate check on create, keyed on the household. Because the household is now
 * keyed on {@code (lastName, postcode)} via a deterministic {@code householdId} (see
 * {@link OwnerHousehold}), owners sharing a lastName and postcode are the same household: a
 * second such owner is a household duplicate and is rejected 409 via
 * {@link DuplicateIdentityException}.
 *
 * <p>{@code sharesHousehold} bypasses this block: a declared household member is allowed to be
 * created (and is not flagged as a possible duplicate downstream — see
 * {@link AssignPossibleDuplicate}). Runs after the householdId is assigned and before the owner
 * is saved.
 */
public class EnsureUniqueOwnerIdentity {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member bypasses the duplicate block
        }
        String householdId = owner.getHouseholdId();
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateIdentityException(OwnerIdentity.of(owner));
            }
        }
    }
}

package org.springframework.samples.petclinic.model;

import java.util.Locale;

/**
 * The single definition of an owner's {@code identityKey}: the one derived value that all
 * duplicate detection is expressed through. It is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
 * telephone is normalized to E.164 via {@link OwnerTelephones} (so a stored value and a
 * freshly created one compare the same way), the email is lower-cased (empty when absent)
 * and the householdId is used as-is (empty when the owner is not in a shared household).
 *
 * <p>Two owners collide only when their WHOLE keys are equal. Because the telephone is part
 * of the key, two members of the same household (same householdId) with different telephones
 * have different keys and are both allowed; only an exact full-key match is a duplicate.
 *
 * <p>Lives beside {@link Owner} so both the mapping layer (which returns the key) and the
 * request-handling layer (which dedups on it) can depend on it without a package cycle.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The owner's {@code identityKey} — see the class javadoc for the exact composition. */
    public static String of(Owner owner) {
        String telephone = OwnerTelephones.toE164OrRaw(owner.getTelephone());
        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
        return telephone + "|" + email + "|" + householdId;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * The single definition of address normalization, applied when an owner is created
 * (see {@link NormalizeOwnerAddress}) and reused by {@link OwnerHousehold} so that every
 * comparison of addresses uses the same normalized form as what is stored and returned.
 *
 * <p>Normalization trims and collapses whitespace runs to a single space, upper-cases the
 * value, and expands the common street-type abbreviations {@code ST->STREET},
 * {@code RD->ROAD} and {@code AVE->AVENUE} (matched as whole space-separated tokens).
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    /**
     * Normalize an address to its canonical stored/compared form. A {@code null} or
     * blank input yields the empty string.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder result = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            String token = tokens[i].toUpperCase(Locale.ROOT);
            token = ABBREVIATIONS.getOrDefault(token, token);
            if (i > 0) {
                result.append(' ');
            }
            result.append(token);
        }
        return result.toString();
    }
}
